// Input struct for geometry creation
struct gkyl_gk_geometry_inp {
  enum gkyl_geometry_id geometry_id;
  char geometry_path[128]; // Path to geometry files

  void *c2p_ctx; // Context for mapc2p function.
  // Pointer to mapc2p function: xc are the computational space
  // coordinates and on output xp are the corresponding physical space
  // coordinates.
  void (*mapc2p)(double t, const double *xc, double *xp, void *ctx);

  void *bfield_ctx; // Context for bfield function.
  // Pointer to bfield function.
  void (*bfield_func)(double t, const double *xc, double *xp, void *ctx);

  // Functions defining the twistshift for parallel BCs.
  void (*lower_shift_func)(double t, const double *xn, double *fout, void *ctx);
  void (*upper_shift_func)(double t, const double *xn, double *fout, void *ctx);
  void *lower_shift_ctx; // Context for lower_shift_func.
  void *upper_shift_ctx; // Context for upper_shift_func.

  struct gkyl_efit_inp efit_info; // Context with RZ data such as efit file for a tokamak or mirror.
  struct gkyl_tok_geo_grid_inp
    tok_grid_info; // Context for tokamak geometry with computational domain info.
  struct gkyl_mirror_geo_grid_inp
    mirror_grid_info; // Context for mirror geometry with computational domain info.
  struct gkyl_position_map *position_map; // Position map object.
  struct gkyl_comm *comm; // Communicator object.

  double world[3]; // Extra computational coordinates for cases with reduced dimensionality.

  bool has_LCFS; // Whether the geometry has a last closed flux surface (LCFS).
  double x_LCFS; // x location of the LCFS.

  // 3D grid ranges and basis.
  struct gkyl_rect_grid geo_grid;
  struct gkyl_range geo_local;
  struct gkyl_range geo_local_ext;
  struct gkyl_range geo_global;
  struct gkyl_range geo_global_ext;
  struct gkyl_basis geo_basis;

  // Grid ranges and basis with cdim of simulation.
  struct gkyl_rect_grid grid;
  struct gkyl_range local;
  struct gkyl_range local_ext;
  struct gkyl_range global;
  struct gkyl_range global_ext;
  struct gkyl_basis basis;
};

/**
 * Create a new geometry object
 * If use-gpu is false, the geometric quantities will be empty, so quantities should be read 
 * from file later on
 * If use-gpu is true, the geometric quantities will be copied from the pre-populated host object
 *
 * @param geo_host gk_geometry object on the host
 *   Unused if calling with use_gpu=false
 *   If use_gpu=true, geo_host must already be initialized.
 * @param geometry_inp geometry input struct containing grid, range, and other geo info
 * @param use_gpu whether or not to use gpu
 */
struct gk_geometry *gkyl_gk_geometry_new(
  struct gkyl_gyrokinetic_projection projection; // Projection object input (e.g. for FIXED_FUNC).
  struct gkyl_gyrokinetic_emission_inp emission;
  bool write_diagnostics; // Whether to output diagnostics.
  int bidx; // Block index (for multiblock solver).
  char aux_str[128]; // Auxiliary string (e.g. path to surrogate model for sheath BCs).
};

// Parameters for BCs in closed flux surfaces.
struct gkyl_gyrokinetic_core_parallel_bcs {
  void (*lower_shift_func)(
    double t, const double *xn, double *fout, void *ctx
  ); // Lower twist-shift function.
  void (*upper_shift_func)(
    double t, const double *xn, double *fout, void *ctx
  ); // Upper twist-shift function.
  void *lower_shift_ctx; // Context for lower twist-shift function.
  void *upper_shift_ctx; // Context for upper twist-shift function.
  int ts_upsample_factor; // Twist-shift supersampling factor (default 4), set to -1 to disable filter.
  int ts_filter_half_width; // Twist-shift filter stencil half-width in cells of the simulation grid (default 1), set to -1 to disable filter.
  double
    ts_filter_cutoff_wavelength; // Twist-shift filter cutoff wavelength (default 2*dx, the coarse mesh Nyquist), set to -1 to disable filter.
};

struct gkyl_gyrokinetic_geometry {
  enum gkyl_geometry_id geometry_id;
  char geometry_path[128]; // Path to geometry files

  // Pointer to mapc2p function: xc are the computational space
  // coordinates and on output xp are the corresponding physical space
  // coordinates.
  void (*mapc2p)(double t, const double *xc, double *xp, void *ctx);
  void *c2p_ctx; // Context for mapc2p function.

  // Pointer to bfield function.
  void (*bfield_func)(double t, const double *xc, double *xp, void *ctx);
  void *bfield_ctx; // Context for bfield function.

  double world[3]; // Extra computational coordinates for cases with reduced dimensionality.

  bool has_LCFS; // Whether the geometry has a last closed flux surface (LCFS).
  double x_LCFS; // x coordinate of the LCFS.

  struct gkyl_gyrokinetic_core_parallel_bcs
    core_parallel_bcs; // BCs info in closed flux surface region.

  struct gkyl_efit_inp efit_info; // Context with RZ data such as efit file for a tokamak or mirror.
  struct gkyl_tok_geo_grid_inp
    tok_grid_info; // Context for tokamak geometry with computational domain info.
  struct gkyl_mirror_geo_grid_inp
    mirror_grid_info; // Context for mirror geometry with computational domain info.
  struct gkyl_position_map_inp position_map_info; // Position map object.
};

// Parameters for species radiation.
struct gkyl_gyrokinetic_radiation {
  enum gkyl_radiation_id radiation_id; // Type of radiation.

  int num_cross_collisions; // Number of species to cross-collide with.
  char collide_with[2 * GKYL_MAX_SPECIES][128]; // Names of species to cross collide with.

  int atomic_Z[2 * GKYL_MAX_SPECIES]; // Z of element for desired fit information.
  // Create plane communicators.
  for (int dir = 0; dir < app->cdim; ++dir) {
    // Identify ranks on the same plane as this one.
    int num_ranks_plane = 0;
    int ranks_plane[app->decomp->ndecomp];
    for (int i = 0; i < app->decomp->ndecomp; i++) {
      if (app->decomp->ranges[i].lower[dir] == app->local.lower[dir]) {
        ranks_plane[num_ranks_plane] = i;
        num_ranks_plane++;
      }
    }
    // Create a range global in perpendicular directions, and local in parallel direction.
    int lower_plane[app->cdim], upper_plane[app->cdim];
    for (int d = 0; d < app->cdim; ++d) {
      lower_plane[d] = app->global.lower[d];
      upper_plane[d] = app->global.upper[d];
    }
    lower_plane[dir] = app->local.lower[dir];
    upper_plane[dir] = app->local.upper[dir];
    struct gkyl_range range_plane;
    gkyl_range_init(&range_plane, app->cdim, lower_plane, upper_plane);

    // Create decomp.
    int cuts_plane[GKYL_MAX_CDIM];
    for (int d = 0; d < app->cdim; ++d) {
      cuts_plane[d] = gk->parallelism.cuts[d];
    }
    cuts_plane[dir] = 1;
    app->decomp_plane[dir] = gkyl_rect_decomp_new_from_cuts(app->cdim, cuts_plane, &range_plane);

    // Create a new communicator with ranks on plane.
    bool is_comm_valid;
    app->comm_plane[dir] = gkyl_comm_create_comm_from_ranks(
      app->comm, num_ranks_plane, ranks_plane, app->decomp_plane[dir], &is_comm_valid
    );
    assert(is_comm_valid);
  }

  // Skin and ghost ranges for configuration space fields.
  for (int dir = 0; dir < cdim; ++dir) {
    gkyl_skin_ghost_ranges(
      &app->local_lower_skin[dir], &app->local_lower_ghost[dir], dir, GKYL_LOWER_EDGE,
      &app->local_ext, ghost
    );
    gkyl_skin_ghost_ranges(
      &app->local_upper_skin[dir], &app->local_upper_ghost[dir], dir, GKYL_UPPER_EDGE,
      &app->local_ext, ghost
    );
    gkyl_skin_ghost_ranges(
      &app->global_lower_skin[dir], &app->global_lower_ghost[dir], dir, GKYL_LOWER_EDGE,
      &app->global_ext, ghost
    );
    gkyl_skin_ghost_ranges(
      &app->global_upper_skin[dir], &app->global_upper_ghost[dir], dir, GKYL_UPPER_EDGE,
      &app->global_ext, ghost
    );
  }

  int comm_sz;
  gkyl_comm_get_size(app->comm, &comm_sz);

  // Configuration space geometry initialization
  app->position_map = gkyl_position_map_new(
    gk->geometry.position_map_info, app->grid, app->local, app->local_ext, app->global,
    app->global_ext, app->basis
  );

  // Initialize the input struct from user side input struct
  struct gkyl_gk_geometry_inp geometry_inp = {
    .geometry_id = gk->geometry.geometry_id,
    .c2p_ctx = gk->geometry.c2p_ctx,
    .mapc2p = gk->geometry.mapc2p,
    .bfield_ctx = gk->geometry.bfield_ctx,
    .bfield_func = gk->geometry.bfield_func,
    .efit_info = gk->geometry.efit_info,
    .tok_grid_info = gk->geometry.tok_grid_info,
    .mirror_grid_info = gk->geometry.mirror_grid_info,
    .position_map = app->position_map,
    .grid = app->grid,
    .local = app->local,
    .local_ext = app->local_ext,
    .global = app->global,
    .global_ext = app->global_ext,
    .basis = app->basis,
    .comm = app->comm,
    .has_LCFS = gk->geometry.has_LCFS,
    .x_LCFS = gk->geometry.x_LCFS,
    .lower_shift_func = gk->geometry.core_parallel_bcs.lower_shift_func,
    .upper_shift_func = gk->geometry.core_parallel_bcs.upper_shift_func,
    .lower_shift_ctx = gk->geometry.core_parallel_bcs.lower_shift_ctx,
    .upper_shift_ctx = gk->geometry.core_parallel_bcs.upper_shift_ctx,
  };
  strcpy(geometry_inp.geometry_path, gk->geometry.geometry_path);
  for (int i = 0; i < 3; i++) {
    geometry_inp.world[i] = gk->geometry.world[i];
  }

  if (app->cdim < 3) {
    geometry_inp.geo_grid = gkyl_gk_geometry_augment_grid(app->grid, geometry_inp);
    switch (gk->basis_type) {
      case GKYL_BASIS_MODAL_SERENDIPITY:
        gkyl_cart_modal_serendip(&geometry_inp.geo_basis, 3, poly_order);
        break;
      default:
        assert(false);
        break;
    }

    int ghost[] = {1, 1, 1};
    gkyl_create_grid_ranges(
      &geometry_inp.geo_grid, ghost, &geometry_inp.geo_global_ext, &geometry_inp.geo_global
    );
    if (comm_sz > 1) {
      // Create local and local_ext from user-supplied local range.
      gkyl_gk_geometry_augment_local(
        &app->local, ghost, &geometry_inp.geo_local_ext, &geometry_inp.geo_local
      );
    } else {
      // Global and local ranges are same, and so just copy.
      memcpy(&geometry_inp.geo_local, &geometry_inp.geo_global, sizeof(struct gkyl_range));
      memcpy(&geometry_inp.geo_local_ext, &geometry_inp.geo_global_ext, sizeof(struct gkyl_range));
    }
  } else {
    geometry_inp.geo_grid = app->grid;
    geometry_inp.geo_local = app->local;
    geometry_inp.geo_local_ext = app->local_ext;
    geometry_inp.geo_global = app->global;
    geometry_inp.geo_global_ext = app->global_ext;
    geometry_inp.geo_basis = app->basis;
  }

  struct gk_geometry *gk_geom_3d;
  switch (geometry_inp.geometry_id) {
    case GKYL_GEOMETRY_FROMFILE:
      gk_geom_3d = gkyl_gk_geometry_new(app->gk_geom, &geometry_inp, false);
      break;
    case GKYL_GEOMETRY_TOKAMAK:
      gk_geom_3d = gkyl_gk_geometry_tok_new(&geometry_inp);
      break;
    case GKYL_GEOMETRY_MIRROR:
      gk_geom_3d = gkyl_gk_geometry_mirror_new(&geometry_inp);
      break;
    case GKYL_GEOMETRY_MAPC2P:
    case GKYL_GEOMETRY_NONE:
      gk_geom_3d = gkyl_gk_geometry_mapc2p_new(&geometry_inp);
      break;
  }

  if (geometry_inp.geometry_id != GKYL_GEOMETRY_FROMFILE) {
    // Deflate geometry if necessary.
    if (app->cdim < 3) {
      app->gk_geom = gkyl_gk_geometry_deflate(gk_geom_3d, &geometry_inp);
    } else {
      app->gk_geom = gkyl_gk_geometry_acquire(gk_geom_3d);
    }
  } else {
    app->gk_geom = gkyl_gk_geometry_acquire(gk_geom_3d);
    gkyl_gyrokinetic_app_read_geometry(app, &geometry_inp);
    gkyl_gk_geometry_populate_nodal(app->gk_geom);
  }

#include <gkyl_alloc.h>
#include <gkyl_alloc_flags_priv.h>
#include <gkyl_array.h>
#include <gkyl_array_ops.h>
#include <gkyl_array_rio.h>
#include <gkyl_basis.h>
#include <gkyl_comm.h>
#include <gkyl_eval_on_nodes.h>
#include <gkyl_gk_geometry.h>
#include <gkyl_gk_geometry_priv.h>
#include <gkyl_gk_geometry_tok.h>
#include <gkyl_math.h>
#include <gkyl_nodal_ops.h>

#include <gkyl_tok_geo.h>
#include <gkyl_rz_calc_derived_geo.h>
#include <gkyl_calc_metric.h>
#include <gkyl_calc_bmag.h>
#include <assert.h>

struct gk_geometry *
gk_geometry_tok_init(struct gkyl_gk_geometry_inp *geometry_inp)
{
  struct gk_geometry *up = gkyl_calloc(1, sizeof(struct gk_geometry));
  up->geometry_id = geometry_inp->geometry_id;
  up->basis = geometry_inp->geo_basis;
  up->local = geometry_inp->geo_local;
  up->local_ext = geometry_inp->geo_local_ext;
  up->global = geometry_inp->geo_global;
  up->global_ext = geometry_inp->geo_global_ext;
  up->grid = geometry_inp->geo_grid;
  up->has_LCFS = geometry_inp->has_LCFS;
  if (up->has_LCFS) {
    up->x_LCFS = geometry_inp->x_LCFS;
    // Check that the split happens within the domain.
    assert((up->grid.lower[0] <= up->x_LCFS) && (up->x_LCFS <= up->grid.upper[0]));
    // Check that the split happens at a cell boundary;
    double needint = (up->x_LCFS - up->grid.lower[0]) / up->grid.dx[0];
    double rem_floor = fabs(needint - floor(needint));
    double rem_ceil = fabs(needint - ceil(needint));
    if (rem_floor < 1.0e-12) {
      up->idx_LCFS_lo = (int)floor(needint);
    } else if (rem_ceil < 1.0e-12) {
      up->idx_LCFS_lo = (int)ceil(needint);
    } else {
      fprintf(stderr, "x_LCFS = %.9e must be at a cell boundary.\n", up->x_LCFS);
      assert(false);
    }
  }

  gk_geometry_set_nodal_ranges(up);

  // Initialize surface basis
  gkyl_cart_modal_serendip(&up->surf_basis, up->grid.ndim - 1, up->basis.poly_order);
  up->num_surf_basis = up->surf_basis.num_basis;

  // Initialize tokamak geometry object from EFIT
  const struct gkyl_efit_inp inp = geometry_inp->efit_info;
  struct gkyl_tok_geo_grid_inp ginp = geometry_inp->tok_grid_info;
  ginp.cgrid = up->grid;
  ginp.cbasis = up->basis;
  struct gkyl_tok_geo *geo = gkyl_tok_geo_new(&inp, &ginp);
  up->geqdsk_sign_convention = geo->efit->sibry > geo->efit->simag ? 0 : 1;
  up->half_domain = ginp.half_domain ? 1 : 0;

  // Allocate nodal and modal arrays for corner, interior, and surface geo
  gk_geometry_corn_alloc_nodal(up);
  gk_geometry_corn_alloc_expansions(up);
  gk_geometry_int_alloc_nodal(up);
  gk_geometry_int_alloc_expansions(up);
  for (int dir = 0; dir < up->grid.ndim; ++dir) {
    gk_geometry_surf_alloc_nodal(up, dir);
    gk_geometry_surf_alloc_expansions(up, dir);
  }

  gkyl_position_map_optimize(geometry_inp->position_map, up->grid, up->global);

  // Calculate bmag and mapc2p in cylindrical coords at corner nodes for
  // getting cell coordinates (used only for plotting).
  gkyl_tok_geo_calc(up, &up->nrange_corn, geo, &ginp, geometry_inp->position_map);
  // Calculate bmag and mapc2p in cylindrical coords at interior nodes for
  // calculating geo quantity volume expansions.
  gkyl_tok_geo_calc_interior(up, &up->nrange_int, up->dzc, geo, &ginp, geometry_inp->position_map);
  // Calculate bmag and mapc2p in cylindrical coords at surfaces.
  for (int dir = 0; dir < up->grid.ndim; dir++) {
    gkyl_tok_geo_calc_surface(
      up, dir, &up->nrange_surf[dir], up->dzc, geo, &ginp, geometry_inp->position_map
    );
  }

  // Now calculate the metrics at interior nodes.
  struct gkyl_calc_metric *mcalc = gkyl_calc_metric_new(
    &up->basis, &up->grid, &up->global, &up->global_ext, &up->local, &up->local_ext, true, false
  );
  gkyl_calc_metric_advance_rz_interior(mcalc, up);
  gkyl_array_copy(up->geo_int.jacobgeo_ghost, up->geo_int.jacobgeo);
  // Calculate neutral metrics at interior nodes.
  gkyl_calc_metric_advance_rz_neut_interior(mcalc, up);
  // Calculate the derived geometric quantities at interior nodes.
  gkyl_rz_calc_derived_geo *jcalculator =
    gkyl_rz_calc_derived_geo_new(&up->basis, &up->grid, 1, false);
  gkyl_rz_calc_derived_geo_advance(
    jcalculator, &up->local, up->geo_int.g_ij, up->geo_int.bmag, up->geo_int.jacobgeo,
    up->geo_int.jacobgeo_inv, up->geo_int.gij, up->geo_int.b_i, up->geo_int.cmag,
    up->geo_int.jacobtot, up->geo_int.jacobtot_inv, up->geo_int.gxxj, up->geo_int.gxyj,
    up->geo_int.gyyj, up->geo_int.gxzj, up->geo_int.eps2
  );
  gkyl_rz_calc_derived_geo_release(jcalculator);
  // Calculate metrics/derived geo quantities at surface.
  for (int dir = 0; dir < up->grid.ndim; dir++) {
    gkyl_calc_metric_advance_rz_surface(mcalc, dir, up);
  }
  gkyl_calc_metric_release(mcalc);
  // Calculate surface expansions.
  for (int dir = 0; dir < up->grid.ndim; dir++) {
    gk_geometry_surf_calc_expansions(up, dir, up->nrange_surf[dir]);
  }

  // Store metadata for I/O.
  char geqdsk_file_name[128];
  get_filename_from_path(geo->efit->filepath, geqdsk_file_name, sizeof(geqdsk_file_name));
  struct gkyl_msgpack_map_elem io_meta_basic[] = {
    {.key = "geometry_type", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = up->geometry_id},
    {
      .key = "geqdsk_sign_convention",
      .elem_type = GKYL_MP_UNSIGNED_INT,
      .uval = up->geqdsk_sign_convention,
    },
    {.key = "geqdsk_file", .elem_type = GKYL_MP_STRING, .cval = geqdsk_file_name},
    {.key = "half_domain", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = up->half_domain}
  };
