  GKYL_GAUSS_QUAD = 0, // Gauss-Legendre quadrature
  GKYL_GAUSS_LOBATTO_QUAD, // Gauss-Lobatto quadrature
  GKYL_POSITIVITY_QUAD // Positivity quadrature nodes
};

