  bool use_gpu; // whether to use the GPU
};

struct gkyl_efit {
  const char *filepath;
  char name[1024]; // name (filepath stripped of full path and extension)
  int nr, nz;
  double rdim, zdim, rcentr, rleft, zmid, rmaxis, zmaxis, simag, sibry, bcentr, current, xdum;
  double rmin, rmax, zmin, zmax;

  double psisep; // Separatrix psi for our DG representation
  double psisep_cubic; // Separatrix psi for our cubic DG representation
  // Can differ from sibry, but we need to keep sibry
  // because fpol, q, etc. are defined based on it

  struct gkyl_basis rzbasis;
  struct gkyl_basis rzbasis_cubic;
  struct gkyl_rect_grid rzgrid;
  struct gkyl_range rzlocal;
  struct gkyl_range rzlocal_ext;
  struct gkyl_rect_grid rzgrid_cubic;
  struct gkyl_range rzlocal_cubic;
  struct gkyl_range rzlocal_cubic_ext;
  struct gkyl_array *psizr;
  struct gkyl_array *psizr_cubic;
  struct gkyl_array *bmagzr;
  struct gkyl_basis_ops_evalf *evf;

  struct gkyl_basis fluxbasis;
  struct gkyl_rect_grid fluxgrid;
  struct gkyl_range fluxlocal;
  struct gkyl_range fluxlocal_ext;
  struct gkyl_array *fpolflux;
  struct gkyl_array *fpolprimeflux;
  struct gkyl_array *qflux;

  int num_xpts; // Number of X-points
  double *Rxpt; // R coordinates of X points
  double *Zxpt; // Z coordinates of X-points

  int num_xpts_cubic; // Number of X-points of cubic rep
  double *Rxpt_cubic; // R coordinates of X points of cubic rep
  double *Zxpt_cubic; // Z coordinates of X-points of cubic rep

  bool reflect;
  bool use_gpu;
};

/**
 * Create new updater which reads in magnetic equilibrium 
 * parameters from a geqdsk file,
 * projects the poloidal flux psi(R,Z), psi/R, psi/R^2 on 
 * the RZ grid,
 * and projects F(psi)= R*B_phi on a poloidal flux grid.
 * Also finds X-points of the EQDSK file.
 *
 * @param inp efit_inp input to create efit updayer
 * @return New updater pointer.
 */

gkyl_efit *gkyl_efit_new(const struct gkyl_efit_inp *inp);

void gkyl_efit_release(gkyl_efit *up);
#include <stdio.h>
#include <math.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdlib.h>
#include <gkyl_rect_grid.h>
#include <gkyl_rect_decomp.h>
#include <gkyl_efit.h>
#include <gkyl_efit_priv.h>

#include <gkyl_array.h>
#include <gkyl_range.h>
#include <gkyl_nodal_ops.h>
#include <assert.h>
#include <ctype.h>

gkyl_efit *
gkyl_efit_new(const struct gkyl_efit_inp *inp)
{
  gkyl_efit *up = gkyl_calloc(1, sizeof(struct gkyl_efit));

  up->reflect = inp->reflect;
  up->use_gpu = inp->use_gpu;
  up->filepath = inp->filepath;
  get_stripped_filename(up->filepath, up->name);

  gkyl_cart_modal_tensor(&up->rzbasis_cubic, 2, 3);
  gkyl_cart_modal_serendip(&up->fluxbasis, 1, inp->flux_poly_order);
  gkyl_cart_modal_tensor(&up->rzbasis, 2, inp->rz_poly_order);

  // Check if file exists using gkyl_check_file_exists and handle error only on rank 0.
  if (!gkyl_check_file_exists(up->filepath)) {
    fprintf(stderr, "efit.c: Failed to open the eqdsk file: %s\n", up->filepath);
    assert(false);
  }

  FILE *ptr = fopen(up->filepath, "r");

  // Read the last two ints in the first line, assuming they are N_R and N_Z.
  int MAX_LINE_LENGTH = 256;
  char first_line[MAX_LINE_LENGTH];
  char *token;
  if (fgets(first_line, sizeof(first_line), ptr) != NULL) {
    // Remove potential newline character from the end of the line.
    first_line[strcspn(first_line, "\n")] = 0;

    // Tokenize the string based on whitespace.
    char temp_line[MAX_LINE_LENGTH];
    strcpy(temp_line, first_line);
    token = strtok(temp_line, " \t\r\n");
    while (token != NULL) {
      // Check if the token is a number.
      int is_number = 1;
      for (int i = 0; i < strlen(token); i++) {
        if (!isdigit((unsigned char)token[i])) {
          is_number = 0;
          break;
        }
      }

      if (is_number) {
        // Store the last two integers.
        up->nr = up->nz;
        up->nz = atoi(token);
      }

      // Get the next token.
      token = strtok(NULL, " \t\r\n");
    }
  }

  // Read the non-array parameters, all are doubles:
  // rdim,zdim,rcentr,rleft,zmid;
  // rmaxis,zmaxis,simag,sibry,bcentr;
  // current,simag,xdum,rmaxis,xdum;
  // zmaxis,xdum,sibry,xdum,xdum;
  size_t status = fscanf(
    ptr, "%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf%lf", &up->rdim, &up->zdim,
    &up->rcentr, &up->rleft, &up->zmid, &up->rmaxis, &up->zmaxis, &up->simag, &up->sibry,
    &up->bcentr, &up->current, &up->simag, &up->xdum, &up->rmaxis, &up->xdum, &up->zmaxis,
    &up->xdum, &up->sibry, &up->xdum, &up->xdum
  );

  // Set zmid to 0 for double null
  if (up->reflect) {
    up->zmid = 0.0;
    up->zmaxis = 0.0;
  }

  // Now we need to make the grid
  up->zmin = up->zmid - up->zdim / 2;
  up->zmax = up->zmid + up->zdim / 2;
  up->rmin = up->rleft;
  up->rmax = up->rleft + up->rdim;

  double rzlower[2] = {up->rmin, up->zmin};
  double rzupper[2] = {up->rmax, up->zmax};
  int rzcells[2] = {0};
  int rzghost[2] = {1, 1};
  if (up->rzbasis.poly_order == 1) {
    rzcells[0] = up->nr - 1;
    rzcells[1] = up->nz - 1;
  }
  if (up->rzbasis.poly_order == 2) {
    rzcells[0] = (up->nr - 1) / 2;
    rzcells[1] = (up->nz - 1) / 2;
  }
  gkyl_rect_grid_init(&up->rzgrid, 2, rzlower, rzupper, rzcells);
  gkyl_create_grid_ranges(&up->rzgrid, rzghost, &up->rzlocal_ext, &up->rzlocal);

  int cells_cubic[2] = {up->nr - 1, up->nz - 1};
  int rzghost_cubic[2] = {0, 0};
  gkyl_rect_grid_init(&up->rzgrid_cubic, 2, rzlower, rzupper, cells_cubic);
  gkyl_create_grid_ranges(
    &up->rzgrid_cubic, rzghost_cubic, &up->rzlocal_cubic_ext, &up->rzlocal_cubic
  );

  double fluxlower[1];
  double fluxupper[1];
  bool step_convention; // True if psi increases toward magnetic axis
  if (up->simag > up->sibry) {
    step_convention = true;
    fluxlower[0] = up->sibry;
    fluxupper[0] = up->simag;
  } else {
    step_convention = false;
    fluxlower[0] = up->simag;
    fluxupper[0] = up->sibry;
  }

  int fluxcells[1] = {0};
  int fluxghost[2] = {1, 1};
  if (up->fluxbasis.poly_order == 1) {
    fluxcells[0] = up->nr - 1;
  }
  if (up->fluxbasis.poly_order == 2) {
    fluxcells[0] = (up->nr - 1) / 2;
  }

  gkyl_rect_grid_init(&up->fluxgrid, 1, fluxlower, fluxupper, fluxcells);
  gkyl_create_grid_ranges(&up->fluxgrid, fluxghost, &up->fluxlocal_ext, &up->fluxlocal);

  // allocate the necessary arrays
  up->psizr = gkyl_array_new(GKYL_DOUBLE, up->rzbasis.num_basis, up->rzlocal_ext.volume);
  up->psizr_cubic =
    gkyl_array_new(GKYL_DOUBLE, up->rzbasis_cubic.num_basis, up->rzlocal_cubic_ext.volume);
  up->bmagzr = gkyl_array_new(GKYL_DOUBLE, up->rzbasis.num_basis, up->rzlocal_ext.volume);
  up->fpolflux = gkyl_array_new(GKYL_DOUBLE, up->fluxbasis.num_basis, up->fluxlocal_ext.volume);
  up->fpolprimeflux =
    gkyl_array_new(GKYL_DOUBLE, up->fluxbasis.num_basis, up->fluxlocal_ext.volume);
  up->qflux = gkyl_array_new(GKYL_DOUBLE, up->fluxbasis.num_basis, up->fluxlocal_ext.volume);

  // Read fpol because we do want that
  int flux_node_nums[1] = {up->nr};
  struct gkyl_range flux_nrange;
  gkyl_range_init_from_shape(&flux_nrange, 1, flux_node_nums);
  struct gkyl_array *fpolflux_n = gkyl_array_new(GKYL_DOUBLE, 1, flux_nrange.volume);
  int fidx[1];
  // fpol is given on a uniform flux grid from the magnetic axis to plasma boundary
  if (step_convention) {
    for (int i = up->nr - 1; i >= 0; i--) {
      fidx[0] = i;
      double *fpol_n = gkyl_array_fetch(fpolflux_n, gkyl_range_idx(&flux_nrange, fidx));
      status = fscanf(ptr, "%lf", fpol_n);
    }
  } else {
    for (int i = 0; i < up->nr; i++) {
      fidx[0] = i;
      double *fpol_n = gkyl_array_fetch(fpolflux_n, gkyl_range_idx(&flux_nrange, fidx));
      status = fscanf(ptr, "%lf", fpol_n);
    }
  }

  struct gkyl_nodal_ops *n2m_flux = gkyl_nodal_ops_new(&up->fluxbasis, &up->fluxgrid, false);
  gkyl_nodal_ops_n2m(
    n2m_flux, &up->fluxbasis, &up->fluxgrid, &flux_nrange, &up->fluxlocal, 1, fpolflux_n,
    up->fpolflux, false
  );

