from datetime import date
from typing import Any, Generator, Iterable, List, TextIO, Union

B0 = 0.0
R0 = 2.0
B_axis = B0
kappa = 2
q0 = 2
def psi_f(R, Z):
  return  -( (R-R0)**2 + (Z**2)/4 )


#RZ box
NW = 257
NH = 257
RMIN,RMAX = 0.5, 6.0
ZMIN,ZMAX = -4.0, 4.0
RDIM = RMAX - RMIN
ZDIM = ZMAX - ZMIN
RLEFT=RMIN
ZMID = (ZMAX+ZMIN)/2.0
