+    if (++expansion > 12) return NAN;
+    bound *= 1.5;
+  }
+  for (int j = 0; j <= 64; ++j) {
+    double u = bound*(j/32.0-1), radius = hypot(u, v);
+    double beta = radius > 0 ? up->eta*v/radius : 0;
+    double dbeta = radius > 0 ? -up->eta*v*u/(radius*radius*radius) : 0;
+    double derivative = cos(beta)-up->inp.a_shift*u/up->inp.r_axis-(u*sin(beta)+v*cos(beta))*dbeta;
+    if (derivative <= 0) return NAN;
+  }
+  double lo = -bound, hi = bound;
+  for (int iter = 0; iter < 50; ++iter) {
+    double middle = (lo+hi)/2;
+    if (gen_miller_R_uv(up, middle, v) < R) lo = middle;
+    else hi = middle;
+  }
+  if (fabs(gen_miller_R_uv(up, (lo+hi)/2, v)-R) > 1e-11*up->inp.r_axis) return NAN;
