        .cross_nu_ctx = &ctx,
        .den_ref = ctx.n0,
        .temp_ref = ctx.Te0,
      },

    .source =
      {
        .source_id = GKYL_PROJ_SOURCE,
        .num_sources = 1,

    .parallelism =
      {
        .use_gpu = app_args.use_gpu,
        .cuts = {app_args.cuts[0], app_args.cuts[1], app_args.cuts[2]},
        .comm = comm,
      },
  };

