// Exercise the Miller app API in core-only, SOL-only, and crossing domains.
#include <gkyl_const.h>
#include <gkyl_gyrokinetic.h>
#include <gkyl_gyrokinetic_run.h>
#include <rt_arg_parse.h>
#include <math.h>
#include <stdio.h>

static double
qprofile(double r_omp, void *ctx)
{
  return 2;
}

static void
density(double t, const double *xn, double *out, void *ctx)
{
  out[0] = 1e18;
}

static void
temperature(double t, const double *xn, double *out, void *ctx)
{
  out[0] = 20*GKYL_ELEMENTARY_CHARGE;
}

static void
zero(double t, const double *xn, double *out, void *ctx)
{
  out[0] = 0;
}

// Independent circular constant-q conversion, used only to choose a crossing
// domain whose LCFS lies exactly at its central psi-cell face.
static double
radius_from_flux(double psi)
{
  // R_axis=2, B_axis=1.5, q=2, hence F/q=1.5.
  double offset = psi/1.5;
  return 2+sqrt(offset*(4-offset));
}

int
main(int argc, char **argv)
{
  struct gkyl_app_args args = parse_app_args(argc, argv);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) MPI_Init(&argc, &argv);
#endif
  struct gkyl_comm *comm = gkyl_gyrokinetic_comms_new(args.use_mpi, args.use_gpu, stderr);
  int rank;
  gkyl_comm_get_rank(comm, &rank);
  const char *names[] = {"core", "sol", "crossing"};
  double psi_boundary = 1.5*0.25/(2+sqrt(4-0.25));
  double bounds[][2] = {{2.25, 2.35}, {2.55, 2.60},
    {radius_from_flux(0.9*psi_boundary), radius_from_flux(1.1*psi_boundary)}};
  int result = 0;
  for (int domain = 0; domain < 3; ++domain) {
    struct gkyl_gk input = {
      .cdim = 3, .lower = {bounds[domain][0], -0.02, -M_PI+1e-10},
      .upper = {bounds[domain][1], 0.02, M_PI-1e-10}, .cells = {2, 2, 4},
      .poly_order = 1, .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
      .num_periodic_dir = 1, .periodic_dirs = {1},
      .geometry = {
        .geometry_id = GKYL_GEOMETRY_MILLER,
        .miller_grid_info = {.r_axis = 2, .b_axis = 1.5, .r_lcfs = 2.5, .qprofile = qprofile},
      },
      .num_species = 2,
      .field = {
        .gkfield_id = GKYL_GK_FIELD_ES, .is_static = true, .zero_init_field = true,
        .poisson_bcs = {
          {.dir = 0, .edge = GKYL_LOWER_EDGE, .type = GKYL_BC_GK_FIELD_DIRICHLET},
          {.dir = 0, .edge = GKYL_UPPER_EDGE, .type = GKYL_BC_GK_FIELD_DIRICHLET},
          {.dir = 1, .edge = GKYL_LOWER_EDGE, .type = GKYL_BC_GK_FIELD_PERIODIC},
          {.dir = 1, .edge = GKYL_UPPER_EDGE, .type = GKYL_BC_GK_FIELD_PERIODIC},
        },
      },
      .parallelism = {.comm = comm, .use_gpu = args.use_gpu,
        .cuts = {args.cuts[0], args.cuts[1], args.cuts[2]}},
    };
    snprintf(input.name, sizeof input.name, "miller_api_%s", names[domain]);
    for (int species = 0; species < 2; ++species) {
      double mass = species == 0 ? GKYL_ELECTRON_MASS : 2*GKYL_PROTON_MASS;
      double temp = 20*GKYL_ELEMENTARY_CHARGE, vth = sqrt(temp/mass);
      enum gkyl_gyrokinetic_bc_type parallel_bc = domain == 0 ?
        GKYL_BC_GK_SPECIES_TWISTSHIFT : GKYL_BC_GK_SPECIES_ABSORB;
      input.species[species] = (struct gkyl_gyrokinetic_species){
        .charge = (species == 0 ? -1 : 1)*GKYL_ELEMENTARY_CHARGE,
        .mass = mass, .vdim = 2, .lower = {-4*vth, 0},
        .upper = {4*vth, 8*temp/1.5}, .cells = {4, 2}, .polarization_density = 1e18,
        .projection = {.proj_id = GKYL_PROJ_MAXWELLIAN_PRIM, .density = density,
          .upar = zero, .temp = temperature},
        .collisionless = {.type = GKYL_GK_COLLISIONLESS_ES},
        .bcs = {
          {.dir = 0, .edge = GKYL_LOWER_EDGE, .type = GKYL_BC_GK_SPECIES_ABSORB},
          {.dir = 0, .edge = GKYL_UPPER_EDGE, .type = GKYL_BC_GK_SPECIES_ABSORB},
          {.dir = 2, .edge = GKYL_LOWER_EDGE, .type = parallel_bc},
          {.dir = 2, .edge = GKYL_UPPER_EDGE, .type = parallel_bc},
        },
      };
      snprintf(input.species[species].name, sizeof input.species[species].name, "%s", species == 0 ? "elc" : "ion");
    }
    gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&input);
    if (!app) { result = 1; break; }
    if (input.geometry.geometry_id != GKYL_GEOMETRY_TOKAMAK ||
        input.geometry.has_LCFS != (domain == 2) || input.upper[0] >= 1) result = 1;
    gkyl_gyrokinetic_app_apply_ic(app, 0);
    struct gkyl_update_status status = gkyl_gyrokinetic_update(app, 1e-12);
    if (!status.success || !(status.dt_actual > 0)) result = 1;
    if (rank == 0) printf("Miller %s: psi=[%.12g, %.12g], step %s\n", names[domain],
      input.lower[0], input.upper[0], status.success ? "passed" : "failed");
    gkyl_gyrokinetic_app_release(app);
    if (result) break;
  }
  gkyl_gyrokinetic_comms_release(comm);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) MPI_Finalize();
#endif
  return result;
}

