// This function will set zmin to be the upper turning point location
void
find_lower_turning_point(
  struct gkyl_tok_geo *geo, double psi_curr, double zup, double *zmin, double tolerance
)
{
  double tol = tolerance ? tolerance : 1e-12;
  int nup = 0;
  double zlo = *zmin;
  double zup_last = zup;
  double R[4], dRdZ[4];
  double dR[4], dZ[4];
  double Rlo[4], dRdZlo[4];
  double dRlo[4], dZlo[4];
  while (true) {
    int nup = R_psiZ(geo, psi_curr, zup, 4, R, dRdZ, dR, dZ);
    int nlo = R_psiZ(geo, psi_curr, zlo, 4, Rlo, dRdZlo, dRlo, dZlo);
    //printf("psi = %g;lo, nup = %d %d; zlo, zup = %g %g\n", psi_curr, nlo, nup, zlo, zup);
    if (nlo > 0) {
      *zmin = zlo;
      break;
    }
    if (nup >= 1) {
      if (fabs(zlo - zup) < tol) {
        *zmin = zup;
        break;
      }
      zup_last = zup;
      zup = (zlo + zup) / 2;
    }
    if (nup == 0) {
      zlo = zup;
      zup = zup_last;
    }
  }
}

