  tok.ftype = GKYL_GEOMETRY_TOKAMAK_IWL;
  tok.rmin = info->rz_bounds[0];
  tok.rmax = info->rz_bounds[1];
  tok.rleft = tok.rmin;
  tok.rright = tok.rmax;
  tok.rclose = inp.r_lcfs;
  tok.zmin = info->rz_bounds[2];
  tok.zmax = info->rz_bounds[3];
