  } else {
    global_failure = failure;
  }
  if (global_failure) {
    if (failure) {
      fprintf(stderr, "Miller initialization (rank %d): %s\n", rank, error);
    }
    gkyl_gen_miller_eqdsk_release(generator);
    return false;
  }
