  gk->upper[0] = psi_upper;
  gk->geometry.geometry_id = GKYL_GEOMETRY_TOKAMAK;
  gk->geometry.efit_info = efit;
  gk->geometry.tok_grid_info = tok;
  gk->geometry.miller_grid_info = inp;
  gk->geometry.has_LCFS = crossing;
