import ast
import io
from pathlib import Path
import tokenize
import inspect

root = Path('gyrokinetic/data/eqdsk')
files = [root / name for name in (
  'gkeyll_gen_miller_eqdsk.py', 'miller_ltx.py', 'miller_d3d.py',
  'miller_tcv.py', 'test_gen_miller_eqdsk.py')]

def normalized_tree(source):
  tree = ast.parse(source)
  for node in ast.walk(tree):
    if isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
      if node.body and isinstance(node.body[0], ast.Expr):
        value = node.body[0].value
        if isinstance(value, ast.Constant) and isinstance(value.value, str):
          value.value = inspect.cleandoc(value.value)
  return ast.dump(tree, include_attributes=False)

formatted = {}
for path in files:
  source = path.read_text()
  lines = source.splitlines(keepends=True)
  shifts = {}
  start = None
  for token in tokenize.generate_tokens(io.StringIO(source).readline):
    if token.type in (tokenize.INDENT, tokenize.DEDENT, tokenize.COMMENT,
                      tokenize.NL, tokenize.ENDMARKER):
      continue
    if start is None and token.type != tokenize.NEWLINE:
      start = token.start[0]
    if token.type == tokenize.NEWLINE and start is not None:
      prefix = len(lines[start-1]) - len(lines[start-1].lstrip(' '))
      assert prefix % 4 == 0, (path, start, prefix)
      for row in range(start, token.end[0]+1):
        shifts[row] = prefix // 2
      start = None
  result = []
  for row, line in enumerate(lines, 1):
    prefix = len(line) - len(line.lstrip(' '))
    shift = shifts.get(row, prefix // 2)
    assert shift <= prefix, (path, row)
    result.append(line[shift:])
  updated = ''.join(result)
  assert normalized_tree(source) == normalized_tree(updated), path
  depth = 0
  for token in tokenize.generate_tokens(io.StringIO(updated).readline):
    if token.type == tokenize.INDENT:
      depth += 1
      assert token.string == '  ' * depth, (path, token.start)
    elif token.type == tokenize.DEDENT:
      depth -= 1
  compile(updated, str(path), 'exec')
  formatted[path] = updated
for path, updated in formatted.items():
  path.write_text(updated)
  print(f'{path}: two-space blocks; syntax and normalized AST verified')
